3. Library size and count-distribution QC

counts_raw = np.asarray(se.get_assay("counts"))
lib_sizes = pd.DataFrame({
    "sample": se.get_column_names(),
    "library_size": counts_raw.sum(axis=0),
    "growth_condition": cd["growth condition"].map({
        "300 millimolar sodium chloride": "salt", "normal watering": "control",
    }).to_numpy(),
    "time": cd["time"].to_numpy(),
})
gg.plot_coldata(lib_sizes, x="time", y="library_size", color_by="growth_condition", shape="box") + theme_bw() + labs(title="Library size by condition and time", y="Total counts")









gene_names = se.get_row_names()
log_counts_long = pd.DataFrame(
    np.log1p(counts_raw[:, :4]), columns=se.get_column_names()[:4]
).melt(var_name="sample", value_name="log1p_count")
gg.plot_coldata(log_counts_long, x="sample", y="log1p_count", shape="violin") + theme_bw() + labs(title="Per-sample count distribution (first 4 samples)", y="log1p(raw count)")

Pseudobulk
plot_pseudobulk_qc is fully covered on Baron in Specialized plots. plot_pseudobulk_de accepts a dict[str, DataFrame] of differential- expression results. Here the keys identify the three E-MTAB-1625 time points:

per_timepoint = {tp: run_deseq2_on_emtab1625(tp)["results"] for tp in ["1 hour", "5 hour", "24 hour"]}
results_by_tp = {tp.replace(" ", "_"): df for tp, df in per_timepoint.items()}
{k: int((df["padj"] &lt; 0.05).sum()) for k, df in results_by_tp.items()}

{'1_hour': 14, '5_hour': 8, '24_hour': 832}



gg.plot_pseudobulk_de(results_by_tp, mode="volcano", ncol=3)









gg.plot_pseudobulk_de(results_by_tp, mode="summary_bar") + theme_bw()








mode="upset" (requires the upsetplot extra) returns a matplotlib Figure directly, showing which significant genes are shared across timepoints:

gg.plot_pseudobulk_de(results_by_tp, mode="upset")
